def find_max(words):
    def count_unique_chars(s):
        return len(set(s))

    max_unique = -1
    result = ""

    for word in words:
        current_unique = count_unique_chars(word)
        if current_unique > max_unique or (current_unique == max_unique and word < result):
            max_unique = current_unique
            result = word

    return result
